import React, { useRef, useEffect } from 'react';

function Waves({
  lineColor = '#4c6b93',
  backgroundColor = 'transparent',
  waveSpeedX = 0.02,
  waveSpeedY = 0.01,
  waveAmpX = 40,
  waveAmpY = 20,
  friction = 0.9,
  tension = 0.01,
  maxCursorMove = 120,
  xGap = 12,
  yGap = 36,
}) {
  const canvasRef = useRef(null);
  const mouseRef = useRef({ x: -1000, y: -1000 });
  const pointsRef = useRef([]);
  const animationRef = useRef(null);
  const timeRef = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    let width, height;

    const init = () => {
      const parent = canvas.parentElement;
      width = parent.clientWidth;
      height = parent.clientHeight;
      canvas.width = width;
      canvas.height = height;

      const points = [];
      for (let y = 0; y < height + yGap; y += yGap) {
        for (let x = 0; x < width + xGap; x += xGap) {
          points.push({
            x,
            y,
            originX: x,
            originY: y,
            vx: 0,
            vy: 0,
            wx: Math.random() * Math.PI * 2,
            wy: Math.random() * Math.PI * 2,
          });
        }
      }
      pointsRef.current = points;
    };

    const draw = () => {
      ctx.clearRect(0, 0, width, height);

      if (backgroundColor && backgroundColor !== 'transparent') {
        ctx.fillStyle = backgroundColor;
        ctx.fillRect(0, 0, width, height);
      }

      const points = pointsRef.current;
      const time = timeRef.current;
      const mouse = mouseRef.current;

      // Update points
      for (const p of points) {
        p.wx += waveSpeedX;
        p.wy += waveSpeedY;

        const waveX = Math.sin(p.wx) * waveAmpX;
        const waveY = Math.cos(p.wy) * waveAmpY;

        const dx = mouse.x - p.originX;
        const dy = mouse.y - p.originY;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const maxDist = maxCursorMove;

        let cursorFx = 0;
        let cursorFy = 0;

        if (dist < maxDist && dist > 0) {
          const force = (1 - dist / maxDist) * 2;
          cursorFx = (-dx / dist) * force;
          cursorFy = (-dy / dist) * force;
        }

        const targetX = p.originX + waveX + cursorFx;
        const targetY = p.originY + waveY + cursorFy;

        p.vx += (targetX - p.x) * tension;
        p.vy += (targetY - p.y) * tension;
        p.vx *= friction;
        p.vy *= friction;
        p.x += p.vx;
        p.y += p.vy;
      }

      // Draw lines
      ctx.strokeStyle = lineColor;
      ctx.lineWidth = 1;

      const cols = Math.ceil(width / xGap) + 1;

      // Horizontal lines
      for (let i = 0; i < points.length; i++) {
        const p = points[i];
        const right = points[i + 1];
        if (right && (i + 1) % cols !== 0) {
          ctx.beginPath();
          ctx.moveTo(p.x, p.y);
          ctx.lineTo(right.x, right.y);
          ctx.stroke();
        }
      }

      // Vertical lines
      for (let i = 0; i < points.length; i++) {
        const p = points[i];
        const below = points[i + cols];
        if (below) {
          ctx.beginPath();
          ctx.moveTo(p.x, p.y);
          ctx.lineTo(below.x, below.y);
          ctx.stroke();
        }
      }

      timeRef.current += 0.01;
      animationRef.current = requestAnimationFrame(draw);
    };

    const handleMouseMove = (e) => {
      const rect = canvas.getBoundingClientRect();
      mouseRef.current = {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
      };
    };

    const handleMouseLeave = () => {
      mouseRef.current = { x: -1000, y: -1000 };
    };

    const handleResize = () => {
      init();
    };

    canvas.addEventListener('mousemove', handleMouseMove);
    canvas.addEventListener('mouseleave', handleMouseLeave);
    window.addEventListener('resize', handleResize);

    init();
    draw();

    return () => {
      cancelAnimationFrame(animationRef.current);
      canvas.removeEventListener('mousemove', handleMouseMove);
      canvas.removeEventListener('mouseleave', handleMouseLeave);
      window.removeEventListener('resize', handleResize);
    };
  }, [lineColor, backgroundColor, waveSpeedX, waveSpeedY, waveAmpX, waveAmpY, friction, tension, maxCursorMove, xGap, yGap]);

  return (
    <canvas
      ref={canvasRef}
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        zIndex: 0,
        pointerEvents: 'auto',
      }}
    />
  );
}

export default Waves;
